#include "zreplay.h"
#include "event_handler.h"
#include "zmap.h"
#include <SDL3/SDL.h>
#include <zlib.h>
#include <cstring>
#include <sstream>
namespace {constexpr std::uint64_t limit=256ULL*1024*1024;void write(std::ostream &out,std::uint64_t n,int size){for(int i=0;i<size;++i)out.put((char)(n>>(i*8)));}bool read(std::istream &in,std::uint64_t &n,int size){n=0;for(int i=0;i<size;++i){int c=in.get();if(c<0)return false;n|=(std::uint64_t)(unsigned char)c<<(i*8);}return true;}}
bool ZReplay_Allowed(int id){switch(id){case NEWS_EVENT:case RESET_GAME:case STORE_MAP:case ADD_NEW_OBJECT:case SET_ZONE_INFO:case SEND_WAYPOINTS:case SEND_UNIT_ROUTE:case SEND_RALLYPOINTS:case SEND_LOC:case SET_OBJECT_TEAM:case SET_ATTACK_OBJECT:case DELETE_OBJECT:case UPDATE_HEALTH:case FIRE_MISSILE:case DESTROY_OBJECT:case SET_BUILDING_STATE:case SET_BUILT_CANNON_AMOUNT:case OBJECT_GROUP_INFO:case DO_CRANE_ANIM:case SET_REPAIR_ANIM:case SET_SETTINGS:case SET_LID_OPEN:case SNIPE_OBJECT:case DRIVER_HIT_EFFECT:case SET_GRENADE_AMOUNT:case PICKUP_GRENADE_ANIM:case SET_BUILDING_QUEUE_LIST:return true;default:return false;}}
bool ZReplay_SafePacket(int id,const char *data,int size){if(!ZReplay_Allowed(id)||size<0)return false;if(id!=NEWS_EVENT)return true;if(!data||size<5||size>2048||!memchr(data+3,0,size-3))return false;std::string text(data+3);return text.compare(0,9,"@session|")==0||text.compare(0,10,"@dialogue|")==0||text.compare(0,11,"@objective|")==0||text.compare(0,12,"@checkpoint|")==0;}
bool ZReplayRecorder::Start(const std::string &target,int team){Finish();path=target;stream.open(path+".part",std::ios::binary|std::ios::trunc);if(!stream)return false;stream.write("ZODRPL1!",8);std::string version=ZOD_VERSION;write(stream,version.size(),4);stream.write(version.data(),version.size());write(stream,team>=1&&team<=4?team:1,4);packets=0;bytes=16+version.size();last=0;complete=false;failed=false;return true;}
bool ZReplayRecorder::Record(std::uint64_t ms,int id,const char *data,int size){if(!Active())return false;if(!ZReplay_SafePacket(id,data,size))return true;if(++packets>200000||ms<last||ms>6ULL*60*60*1000||size<0||size>2*1024*1024||(size&&!data)||bytes+size+20>limit){failed=true;return false;}write(stream,ms,8);write(stream,id,4);write(stream,size,4);write(stream,crc32(0,(const Bytef*)data,size),4);if(size)stream.write(data,size);last=ms;bytes+=size+20;if(id==STORE_MAP&&size>=4){int index;memcpy(&index,data,4);if(index==-1)complete=true;}if(!stream){failed=true;return false;}return true;}
bool ZReplayRecorder::Finish(){if(!Active())return false;stream.flush();bool ok=stream.good()&&complete&&!failed;stream.close();if(ok)ok=SDL_RenamePath((path+".part").c_str(),path.c_str());if(!ok)SDL_RemovePath((path+".part").c_str());return ok;}
bool ZReplayTape::Load(const std::string &path,std::string &error){ZReplayTape candidate;std::ifstream in(path,std::ios::binary|std::ios::ate);auto fail=[&](const char *why){error=why;return false;};if(!in||in.tellg()<16||in.tellg()>(std::streamoff)limit)return fail("Replay missing or exceeds 256 MB");in.seekg(0);char magic[8];in.read(magic,8);if(std::memcmp(magic,"ZODRPL1!",8))return fail("Unsupported replay format");std::uint64_t length,team;if(!read(in,length,4)||(!length||length>32))return fail("Invalid replay header");std::string version(length,' ');in.read(&version[0],length);if(version!=ZOD_VERSION)return fail("Replay requires engine version matching its recording");if(!read(in,team,4)||team<1||team>4)return fail("Invalid replay team");candidate.team=team;std::vector<char> map;bool complete=false;int nextMap=0;while(in.peek()!=EOF){ZReplayPacket packet;std::uint64_t id,size,crc;if(candidate.packets.size()>=200000||!read(in,packet.ms,8)||!read(in,id,4)||!read(in,size,4)||!read(in,crc,4)||size>2*1024*1024||packet.ms<candidate.duration||packet.ms>21600000||!ZReplay_Allowed(id))return fail("Invalid replay packet");packet.id=id;packet.data.resize(size);if(size&&!in.read(packet.data.data(),size))return fail("Truncated replay packet");if(!ZReplay_SafePacket(id,packet.data.data(),size))return fail("Unsupported replay payload");if(id==NEWS_EVENT){std::string text(packet.data.data()+3);if(text.compare(0,9,"@session|")==0){std::istringstream fields(text.substr(9));std::getline(fields,candidate.campaign,'|');std::getline(fields,candidate.mission,'|');}}if(crc32(0,(const Bytef*)packet.data.data(),size)!=crc)return fail("Replay checksum mismatch");if(id==STORE_MAP){if(complete||size<4)return fail("Invalid replay map");int index;std::memcpy(&index,packet.data.data(),4);if(index==-1){ZMap check;if(map.empty()||!check.Read(map.data(),map.size(),true))return fail("Invalid replay map contents");candidate.mapName=check.GetMapBasics().map_name;complete=true;}else{if(index!=nextMap++||map.size()+size-4>16*1024*1024)return fail("Invalid replay map sequence");map.insert(map.end(),packet.data.begin()+4,packet.data.end());}}candidate.duration=packet.ms;candidate.packets.push_back(std::move(packet));}if(!complete)return fail("Replay has no complete map");*this=std::move(candidate);error.clear();return true;}

bool ZReplay_Recover(const std::string &partial,std::string &output,std::string &error){
 output.clear();std::ifstream in(partial,std::ios::binary|std::ios::ate);if(!in||in.tellg()>(std::streamoff)limit){error="Recording missing or too large";return false;}in.seekg(0);char magic[8];in.read(magic,8);std::uint64_t length,team;if(!in||memcmp(magic,"ZODRPL1!",8)||!read(in,length,4)||!length||length>32){error="Invalid recording header";return false;}std::string version(length,' ');in.read(&version[0],length);if(!in||version!=ZOD_VERSION||!read(in,team,4)||team<1||team>4){error="Recording requires its original engine version";return false;}
 std::streamoff good=in.tellg();int packets=0;while(in.peek()!=EOF){std::uint64_t ms,id,size,crc;if(!read(in,ms,8)||!read(in,id,4)||!read(in,size,4)||!read(in,crc,4))break;if(++packets>200000||size>2*1024*1024||!ZReplay_Allowed(id)){error="Corrupt recording packet";return false;}std::vector<char> data(size);if(size&&!in.read(data.data(),size))break;if(crc32(0,(const Bytef*)data.data(),size)!=crc){error="Recording checksum mismatch; file preserved";return false;}good=in.tellg();}
 in.clear();in.seekg(0);std::string destination=partial+".recovered.zreplay",temp=destination+".tmp";SDL_PathInfo info;if(SDL_GetPathInfo(destination.c_str(),&info)){error="Recovered recording already exists";return false;}std::ofstream out(temp,std::ios::binary);char buffer[65536];std::streamoff remaining=good;while(remaining>0){auto count=std::min<std::streamoff>(remaining,sizeof(buffer));if(!in.read(buffer,count)||!out.write(buffer,count)){error="Could not recover recording";out.close();SDL_RemovePath(temp.c_str());return false;}remaining-=count;}out.close();ZReplayTape check;if(!out||!check.Load(temp,error)){SDL_RemovePath(temp.c_str());return false;}if(!SDL_RenamePath(temp.c_str(),destination.c_str())){error="Could not save recovery";SDL_RemovePath(temp.c_str());return false;}output=destination;return true;
}
